        (h, c) => ((h << 5) - h + c.charCodeAt(0)) | 0, 0
    );
    const stableHardwareConcurrency = [4, 8][Math.abs(profileHash) % 2];
    Object.defineProperty(navigator, 'hardwareConcurrency', {
        get: () => stableHardwareConcurrency,
        configurable: true,
    });

    // 8. deviceMemory
    const stableDeviceMemory = [4, 8][(Math.abs(profileHash) + 1) % 2];
    Object.defineProperty(navigator, 'deviceMemory', {
        get: () => stableDeviceMemory,
        configurable: true,
    });

    // 9. navigator.connection
    Object.defineProperty(navigator, 'connection', {
        get: () => ({
            effectiveType: '4g',
            downlink: 10,
            rtt: 50,
            saveData: false,
        }),
        configurable: true,
    });

    // 10. chrome.csi / chrome.loadTimes
    if (window.chrome) {
        window.chrome.csi = function() { return {}; };
        window.chrome.loadTimes = function() { return {}; };
    }

    // 11. outerWidth/outerHeight
    Object.defineProperty(window, 'outerWidth', {
        get: () => window.innerWidth,
        configurable: true,
    });
    Object.defineProperty(window, 'outerHeight', {
        get: () => window.innerHeight,
        configurable: true,
    });
})();
"""

# Chrome 启动参数（反检测相关）
STEALTH_ARGS = [
    "--disable-blink-features=AutomationControlled",
    "--disable-infobars",
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-background-timer-throttling",
    "--disable-backgrounding-occluded-windows",
    "--disable-renderer-backgrounding",
    "--disable-component-update",
    "--disable-extensions",
    "--disable-sync",
    "--use-mock-keychain",
    "--password-store=basic",
]

